14	// This file covers the command-line contract of fault-domain spreading
15	// (spreadBy): the library rules already have unit tests in plan_test.go; here
16	// the same guarantees are observed through `darksafe plan <file>` exactly as a
17	// user drives it — a config file on disk, JSON on stdout, errors on stderr and
18	// process exit codes. Everything runs offline: the binary never connects to a
19	// cluster or performs a release.
20	
21	// cliPlan mirrors the JSON shape of a printed ReleasePlan.
22	type cliPlan struct {
23		App      cliApp        `json:"app"`
24		Batches  []cliBatch    `json:"batches"`
25		Excluded []cliExcluded `json:"excluded"`
26	}
27	
28	type cliApp struct {
29		Name     string `json:"name"`
30		Revision string `json:"revision"`
31		Image    string `json:"image"`
32	}
33	
34	type cliBatch struct {
35		Index    int      `json:"index"`
36		Clusters []string `json:"clusters"`
37	}
38	
39	type cliExcluded struct {
40		ID     string `json:"id"`
41		Reason string `json:"reason"`
42	}
43	
44	// writePlanDoc stores doc in a fresh temp directory and returns its path.
45	func writePlanDoc(t *testing.T, doc string) string {
46		t.Helper()
47		path := filepath.Join(t.TempDir(), "plan.json")
48		if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
49			t.Fatal(err)
50		}
51		return path
52	}
53	
54	// decodeCLIPlan requires stdout to hold exactly one complete JSON plan and
55	// nothing after it: success means stdout contains only the plan.
56	func decodeCLIPlan(t *testing.T, stdout string) cliPlan {
57		t.Helper()
58		dec := json.NewDecoder(strings.NewReader(stdout))
59		var p cliPlan
60		if err := dec.Decode(&p); err != nil {
61			t.Fatalf("stdout is not a parseable JSON plan: %v; stdout=%q", err, stdout)
62		}
63		if err := dec.Decode(&struct{}{}); err != io.EOF {
64			t.Fatalf("stdout carries data after the plan: %q", stdout)
65		}
66		return p
67	}
68	
69	// assertBatches checks batch numbering, size, ascending order, domain
70	// uniqueness per batch and that every selected ID appears exactly once.
71	func assertSpreadBatches(t *testing.T, p cliPlan, want [][]string, domains map[string]string, batchSize int) {
72		t.Helper()
73		if len(p.Batches) != len(want) {
74			t.Fatalf("got %d batches %v, want %d batches %v", len(p.Batches), p.Batches, len(want), want)
75		}
76		seen := map[string]int{}
77		for i, w := range want {
78			b := p.Batches[i]
79			if b.Index != i+1 {
80				t.Fatalf("batch %d has index %d, want %d", i, b.Index, i+1)
81			}
82			if len(b.Clusters) > batchSize {
83				t.Fatalf("batch %d holds %d clusters, batchSize is %d", i+1, len(b.Clusters), batchSize)
84			}
85			if strings.Join(b.Clusters, ",") != strings.Join(w, ",") {
86				t.Fatalf("batch %d = %v, want %v", i+1, b.Clusters, w)
87			}
88			if !sort.StringsAreSorted(b.Clusters) {
89				t.Fatalf("batch %d is not ascending: %v", i+1, b.Clusters)
90			}
91			usedDomain := map[string]string{}
92			for _, id := range b.Clusters {
93				if prev, dup := seen[id]; dup {
94					t.Fatalf("cluster %q appears in batch %d and again in batch %d", id, prev, i+1)
95				}
96				seen[id] = i + 1
97				d, known := domains[id]
98				if !known {
99					t.Fatalf("cluster %q in plan but no expected domain", id)
100				}
101				if other, conflict := usedDomain[d]; conflict {
102					t.Fatalf("batch %d contains two clusters of domain %q: %q and %q", i+1, d, other, id)
103				}
104				usedDomain[d] = id
105			}
106		}
107	}
108	
109	// TestPlanCLI_SpreadByFullPlan drives the whole contract through the CLI:
110	// complete parseable JSON plan, app/revision/image echoed from the input,
111	// fault-domain-aware batching, ascending excluded list with existing reasons,
112	// exit code 0, plan-only stdout and an empty stderr. Candidates are listed out
113	// of order in the file; that must not change any of the results.
114	func TestPlanCLI_SpreadByFullPlan(t *testing.T) {
115		doc := `{
116	  "app": "payments",
117	  "revision": "2026.10.0-r3",
118	  "image": "registry.example.net/payments:2026.10.0-r3",
119	  "batchSize": 3,
120	  "spreadBy": "zone",
121	  "include": [{"zone": "z1"}, {"zone": "z2"}, {"zone": "z3"}],
122	  "exclude": [{"env": "temp"}],
123	  "clusters": [
124	    {"id": "c-d", "tags": {"zone": "z3"}},
125	    {"id": "x2", "tags": {"env": "temp"}},
126	    {"id": "c-b", "tags": {"zone": "z1"}},
127	    {"id": "x1", "tags": {"env": "dev"}},
128	    {"id": "off", "disabled": true},
129	    {"id": "c-e", "tags": {"zone": "z2"}},
130	    {"id": "c-a", "tags": {"zone": "z1"}},
131	    {"id": "c-c", "tags": {"zone": "z2"}}
132	  ]
133	}`
134		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
135		if code != 0 {
136			t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
137		}
138		if stderr != "" {
139			t.Fatalf("expected empty stderr on success, got %q", stderr)
140		}
141	
142		p := decodeCLIPlan(t, stdout)
143		if p.App.Name != "payments" || p.App.Revision != "2026.10.0-r3" ||
144			p.App.Image != "registry.example.net/payments:2026.10.0-r3" {
145			t.Fatalf("app info not echoed from input: %+v", p.App)
146		}
147	
148		// Sorted selection is c-a,c-b (z1), c-c,c-e (z2), c-d (z3). Batch 1 takes
149		// the smallest IDs that fit: c-a(z1), c-c(z2), c-d(z3); c-b and c-e are
150		// deferred by domain conflicts and form batch 2.
151		domains := map[string]string{
152			"c-a": "z1", "c-b": "z1",
153			"c-c": "z2", "c-e": "z2",
154			"c-d": "z3",
155		}
156		assertSpreadBatches(t, p,
157			[][]string{{"c-a", "c-c", "c-d"}, {"c-b", "c-e"}},
158			domains, 3)
159	
160		wantExcluded := []cliExcluded{
161			{ID: "off", Reason: ReasonDisabled},
162			{ID: "x1", Reason: ReasonIncludeNotMatched},
163			{ID: "x2", Reason: ReasonExcludeMatched},
164		}
165		if len(p.Excluded) != len(wantExcluded) {
166			t.Fatalf("excluded = %+v, want %+v", p.Excluded, wantExcluded)
167		}
168		for i, w := range wantExcluded {
169			if p.Excluded[i] != w {
170				t.Fatalf("excluded[%d] = %+v, want %+v", i, p.Excluded[i], w)
171			}
172		}
173	}
174	
175	// TestPlanCLI_SpreadByConflictDefersButDoesNotBlock isolates the core rule:
176	// a same-domain conflict defers that cluster to a later batch, but later
177	// clusters of other domains still enter the current batch, and each batch is
178	// filled from the smallest still-unscheduled ID that can enter it.
179	func TestPlanCLI_SpreadByConflictDefersButDoesNotBlock(t *testing.T) {
180		doc := `{
181	  "app": "app", "revision": "r1", "image": "img",
182	  "batchSize": 2, "spreadBy": "zone",
183	  "clusters": [
184	    {"id": "d", "tags": {"zone": "z2"}},
185	    {"id": "a", "tags": {"zone": "z1"}},
186	    {"id": "b", "tags": {"zone": "z1"}},
187	    {"id": "c", "tags": {"zone": "z2"}}
188	  ]
189	}`
190		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
191		if code != 0 {
192			t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
193		}
194		if stderr != "" {
195			t.Fatalf("unexpected stderr: %q", stderr)
196		}
197		p := decodeCLIPlan(t, stdout)
198		domains := map[string]string{"a": "z1", "b": "z1", "c": "z2", "d": "z2"}
199		// b conflicts with a and is deferred; c (other domain) still joins batch 1.
200		assertSpreadBatches(t, p, [][]string{{"a", "c"}, {"b", "d"}}, domains, 2)
201	}
202	
203	// TestPlanCLI_SpreadByIndependentOfFileOrder runs the same configuration with
204	// candidates in two different orders and requires byte-identical plans, plus
205	// the expected fault-domain schedule.
206	func TestPlanCLI_SpreadByIndependentOfFileOrder(t *testing.T) {
207		template := `{
208	  "app": "app", "revision": "r1", "image": "img",
209	  "batchSize": 2, "spreadBy": "zone",
210	  "clusters": [%s]
211	}`
212		orderA := `
213	    {"id": "a", "tags": {"zone": "z1"}},
214	    {"id": "b", "tags": {"zone": "z1"}},
215	    {"id": "c", "tags": {"zone": "z2"}},
216	    {"id": "d", "tags": {"zone": "z2"}},
217	    {"id": "e", "tags": {"zone": "z3"}}`
218		orderB := `
219	    {"id": "e", "tags": {"zone": "z3"}},
220	    {"id": "c", "tags": {"zone": "z2"}},
221	    {"id": "a", "tags": {"zone": "z1"}},
222	    {"id": "d", "tags": {"zone": "z2"}},
223	    {"id": "b", "tags": {"zone": "z1"}}`
224	
225		code1, out1, err1 := runCLI(t, "plan", writePlanDoc(t, fmt.Sprintf(template, orderA)))
226		code2, out2, err2 := runCLI(t, "plan", writePlanDoc(t, fmt.Sprintf(template, orderB)))
227		if code1 != 0 || code2 != 0 {
228			t.Fatalf("expected exit 0 both runs, got %d (%q) and %d (%q)", code1, err1, code2, err2)
229		}
230		if err1 != "" || err2 != "" {
231			t.Fatalf("unexpected stderr: %q / %q", err1, err2)
232		}
233		if strings.TrimSpace(out1) != strings.TrimSpace(out2) {
234			t.Fatalf("file order changed the plan:\n%s\n----\n%s", out1, out2)
235		}
236		p := decodeCLIPlan(t, out1)
237		domains := map[string]string{"a": "z1", "b": "z1", "c": "z2", "d": "z2", "e": "z3"}
238		assertSpreadBatches(t, p, [][]string{{"a", "c"}, {"b", "d"}, {"e"}}, domains, 2)
239	}
240	
241	// TestPlanCLI_SpreadByFilteringPrecedesTagCheck protects the ordering between
242	// selection filters and the fault-domain check: clusters that are disabled or
243	// removed by include/exclude need no spreadBy tag at all — their missing tag
244	// must not fail a plan that otherwise works. They still appear in the excluded
245	// list, ascending by ID, with their existing reasons. Exclude wins when a
246	// cluster matches both include and exclude.
247	func TestPlanCLI_SpreadByFilteringPrecedesTagCheck(t *testing.T) {
248		doc := `{
249	  "app": "app", "revision": "r1", "image": "img",
250	  "batchSize": 2, "spreadBy": "zone",
251	  "include": [{"env": "prod"}],
252	  "exclude": [{"env": "temp"}, {"quarantine": "true"}],
253	  "clusters": [
254	    {"id": "s1", "tags": {"env": "prod", "zone": "z1"}},
255	    {"id": "tmp", "tags": {"env": "temp"}},
256	    {"id": "off", "disabled": true},
257	    {"id": "s2", "tags": {"env": "prod", "zone": "z2"}},
258	    {"id": "dev", "tags": {"env": "dev"}},
259	    {"id": "both", "tags": {"env": "prod", "quarantine": "true"}}
260	  ]
261	}`
262		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
263		if code != 0 {
264			t.Fatalf("filtered-out clusters must not require the zone tag; exit=%d stderr=%q", code, stderr)
265		}
266		if stderr != "" {
267			t.Fatalf("unexpected stderr: %q", stderr)
268		}
269		p := decodeCLIPlan(t, stdout)
270		domains := map[string]string{"s1": "z1", "s2": "z2"}
271		assertSpreadBatches(t, p, [][]string{{"s1", "s2"}}, domains, 2)
272	
273		wantExcluded := []cliExcluded{
274			{ID: "both", Reason: ReasonExcludeMatched},
275			{ID: "dev", Reason: ReasonIncludeNotMatched},
276			{ID: "off", Reason: ReasonDisabled},
277			{ID: "tmp", Reason: ReasonExcludeMatched},
278		}
279		if len(p.Excluded) != len(wantExcluded) {
280			t.Fatalf("excluded = %+v, want %+v", p.Excluded, wantExcluded)
281		}
282		for i, w := range wantExcluded {
283			if p.Excluded[i] != w {
284				t.Fatalf("excluded[%d] = %+v, want %+v (full list: %+v)", i, p.Excluded[i], w, p.Excluded)
285			}
286		}
287	}
288	
289	// TestPlanCLI_SpreadBySelectedMissingTagFails covers the failure contract: if
290	// any selected cluster lacks the spreadBy tag, planning fails with a non-zero
291	// exit, stdout is completely empty (no partial batches are ever emitted) and
292	// stderr names both the smallest offending cluster and the tag.
293	func TestPlanCLI_SpreadBySelectedMissingTagFails(t *testing.T) {
294		doc := `{
295	  "app": "app", "revision": "r1", "image": "img",
296	  "batchSize": 2, "spreadBy": "zone",
297	  "clusters": [
298	    {"id": "c-a", "tags": {"zone": "east"}},
299	    {"id": "c-c", "tags": {"region": "us"}},
300	    {"id": "c-b"}
301	  ]
302	}`
303		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
304		if code == 0 {
305			t.Fatalf("expected non-zero exit, got 0; stdout=%q", stdout)
306		}
307		if stdout != "" {
308			t.Fatalf("stdout must be empty on failure, got %q", stdout)
309		}
310		if !strings.Contains(stderr, "c-b") {
311			t.Fatalf("stderr must name the smallest offending cluster c-b, got %q", stderr)
312		}
313		if !strings.Contains(stderr, "zone") {
314			t.Fatalf("stderr must name the missing tag zone, got %q", stderr)
315		}
316		if strings.Contains(stderr, "c-c") {
317			t.Fatalf("with multiple offenders stderr must point at the smallest c-b, got %q", stderr)
318		}
319	}
320	
321	// TestPlanCLI_SpreadByEmptyTagValueIsDomain verifies through the CLI that a
322	// tag present with an empty string value is a legal fault domain, distinct
323	// from a missing tag: empty-valued clusters avoid each other but still share
324	// batches with other domains.
325	func TestPlanCLI_SpreadByEmptyTagValueIsDomain(t *testing.T) {
326		doc := `{
327	  "app": "app", "revision": "r1", "image": "img",
328	  "batchSize": 2, "spreadBy": "zone",
329	  "clusters": [
330	    {"id": "c", "tags": {"zone": "east"}},
331	    {"id": "a", "tags": {"zone": ""}},
332	    {"id": "b", "tags": {"zone": ""}}
333	  ]
334	}`
335		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
336		if code != 0 {
337			t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
338		}
339		if stderr != "" {
340			t.Fatalf("unexpected stderr: %q", stderr)
341		}
342		p := decodeCLIPlan(t, stdout)
343		domains := map[string]string{"a": "", "b": "", "c": "east"}
344		// a and b share the empty domain and must not share a batch; c fills batch 1.
345		assertSpreadBatches(t, p, [][]string{{"a", "c"}, {"b"}}, domains, 2)
346	}
347	
348	// TestPlanCLI_NoSpreadByKeepsLegacyBatching verifies that omitting spreadBy
349	// or setting it to "" preserves the original behavior at the CLI level:
350	// ascending IDs split purely by capacity, so clusters of the same domain may
351	// share a batch. Both spellings must produce identical output.
352	func TestPlanCLI_NoSpreadByKeepsLegacyBatching(t *testing.T) {
353		docs := map[string]string{
354			"absent": `{
355	  "app": "app", "revision": "r1", "image": "img",
356	  "batchSize": 2,
357	  "clusters": [
358	    {"id": "c3"},
359	    {"id": "c1", "tags": {"zone": "east"}},
360	    {"id": "c2", "tags": {"zone": "east"}}
361	  ]
362	}`,
363			"empty": `{
364	  "app": "app", "revision": "r1", "image": "img",
365	  "batchSize": 2, "spreadBy": "",
366	  "clusters": [
367	    {"id": "c2", "tags": {"zone": "east"}},
368	    {"id": "c3"},
369	    {"id": "c1", "tags": {"zone": "east"}}
370	  ]
371	}`,
372		}
373		outputs := map[string]string{}
374		for name, doc := range docs {
375			code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
376			if code != 0 {
377				t.Fatalf("%s: expected exit 0, got %d; stderr=%q", name, code, stderr)
378			}
379			if stderr != "" {
380				t.Fatalf("%s: unexpected stderr: %q", name, stderr)
381			}
382			outputs[name] = strings.TrimSpace(stdout)
383		}
384		if outputs["absent"] != outputs["empty"] {
385			t.Fatalf("absent and empty spreadBy differ:\n%s\n----\n%s", outputs["absent"], outputs["empty"])
386		}
387		p := decodeCLIPlan(t, outputs["absent"])
388		// Legacy packing ignores domains: the two same-domain clusters c1 and c2
389		// share batch 1, ordered ascending; c3 takes batch 2.
390		if len(p.Batches) != 2 {
391			t.Fatalf("expected 2 batches, got %+v", p.Batches)
392		}
393		if strings.Join(p.Batches[0].Clusters, ",") != "c1,c2" {
394			t.Fatalf("batch 1 = %v, want [c1 c2] (same domain may share a batch)", p.Batches[0].Clusters)
395		}
396		if p.Batches[0].Index != 1 || p.Batches[1].Index != 2 {
397			t.Fatalf("batch indices must run from 1 consecutively, got %d and %d", p.Batches[0].Index, p.Batches[1].Index)
398		}
399		if strings.Join(p.Batches[1].Clusters, ",") != "c3" {
400			t.Fatalf("batch 2 = %v, want [c3]", p.Batches[1].Clusters)
401		}
402	}
